// Matematik — Çarpanlar ve Katlar: Kademe 2 (Pekiştirme) yedeği, mat-ck-226 … 275
window.LGS_BANK = window.LGS_BANK || {};
(window.LGS_BANK["carpanlar-katlar"] = window.LGS_BANK["carpanlar-katlar"] || []).push(
{
  id: "mat-ck-226",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Mina, 180 sayısını önce 10 · 18 çarpımı olarak yazmış, sonra çarpanların her birini kendi içinde asal çarpanlarına ayırmıştır.\n**Buna göre Mina'nın sonunda elde ettiği asal çarpanlara ayrılmış biçim aşağıdakilerden hangisidir?**",
  gorsel: null,
  secenekler: ["2^{2} · 3^{2} · 5","2^{2} · 3 · 5^{2}","2 · 3^{2} · 5^{2}","2^{3} · 3^{2} · 5"],
  dogru: 0,
  hatalar: [null,"Üsleri yanlış asal çarpanlara koyma: 2^{2} · 3 · 5^{2} = 300 eder, 180 etmez.","5'i iki kez yazma: 2 · 3^{2} · 5^{2} = 450 eder, 180 etmez.","2'yi bir kez fazla sayma: 2^{3} · 3^{2} · 5 = 360 eder; 10 ve 18'den gelen 2'ler iki tanedir."],
  aciklama: "Asal çarpanlarına ayırmak, bir sayıyı yalnızca asal sayıların çarpımı olarak yazmaktır. Hangi iki çarpanla başlarsan başla çarpan ağacının uçlarında aynı asal sayılar çıkar.\nAdım 1: 10 = 2 · 5 ve 18 = 2 · 3 · 3 olarak ayrılır.\nAdım 2: Uçlardaki asalları yan yana yaz: 180 = 2 · 5 · 2 · 3 · 3.\nAdım 3: Aynı asalları üslü göster: 2 iki kez, 3 iki kez, 5 bir kez; 180 = 2^{2} · 3^{2} · 5.\nSağlama: 4 · 9 · 5 = 180.\nSık yapılan hata: Üsleri doğru asallara yazmamak. Her asalın kaç kez geçtiğini ayrı ayrı say.\nCevap A."
},
{
  id: "mat-ck-227",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 2,
  soru: "Bir kitabevinin çekilişinde 35 ile aralarında asal olan numaralı bilet kazanacaktır. Aşağıda verilen dört bilet numarasından yalnızca biri bu koşula uymaktadır.\n**Buna göre kazanan bilet numarası hangisidir?**",
  gorsel: null,
  secenekler: ["14","18","25","49"],
  dogru: 1,
  hatalar: ["Çift sayı olunca ortak böleni olmadığını sanma: 14 = 2 · 7 ve 35 = 5 · 7 olduğundan ikisi de 7'ye bölünür.",null,"25 = 5 · 5 ve 35 = 5 · 7 olduğundan ikisi de 5'e bölünür; ortak bölenleri 1 değildir.","49 = 7 · 7 ve 35 = 5 · 7 olduğundan ikisi de 7'ye bölünür; 49'un asal olmaması ortak böleni ortadan kaldırmaz."],
  aciklama: "İki sayının 1'den başka ortak pozitif böleni yoksa bu sayılar aralarında asaldır. Önce 35'in asal çarpanlarını bul: 35 = 5 · 7. Aranan sayı ne 5'e ne de 7'ye bölünmemelidir.\nAdım 1: 14 = 2 · 7, 7'ye bölünür; elenir.\nAdım 2: 25 = 5 · 5, 5'e bölünür; elenir.\nAdım 3: 49 = 7 · 7, 7'ye bölünür; elenir.\nAdım 4: 18 = 2 · 3^{2}; 5 ya da 7 çarpanı yok. EBOB(18, 35) = 1.\nSık yapılan hata: Yalnızca çift ya da tek olmaya bakmak. Önemli olan iki sayının ortak bir asal çarpanı olup olmadığıdır.\nCevap B."
},
{
  id: "mat-ck-228",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Matematik öğretmeni, tahtaya dört ayrı durum yazmış ve bunlardan yalnızca birinin EKOK ile çözüldüğünü söylemiştir.\n**Buna göre EKOK ile çözülen durum aşağıdakilerden hangisidir?**",
  gorsel: null,
  secenekler: ["İki ipi, artmayacak biçimde ve olabildiğince uzun eşit parçalara ayırmak.","60 ve 90 adet kalemi, artmadan olabildiğince çok kutuya eşit paylaştırmak.","Aynı anda çalan iki zamanlayıcının ilk kez yeniden birlikte çalacağı anı bulmak.","Bir sınıftaki 30 öğrenciyi, 5 kişilik eşit gruplara ayırıp grup sayısını bulmak."],
  dogru: 2,
  hatalar: ["Parçalara ayırma EBOB ister: parça uzunluğu iki uzunluğu da kalansız bölmelidir.","Eşit paylaştırma ve en çok kutu EBOB ister: kutu sayısı iki sayıyı da kalansız bölmelidir.",null,"Tek bir sayıyı bölmek yeterlidir (30 : 5); ortak kat ya da ortak bölen aranmaz."],
  aciklama: "EBOB, iki sayıyı birden kalansız bölen en büyük sayıdır; bölme ve eşit paylaştırma problemlerinde kullanılır. EKOK, iki sayının ortak katlarının en küçüğüdür; tekrar eden olayların yeniden buluşma anını bulmada kullanılır.\nAdım 1: İpi parçalama ve kalemleri kutulara paylaştırma \"bölme\" işidir; EBOB gerekir.\nAdım 2: 30 öğrenciyi gruplama tek sayıyla yapılan basit bir bölmedir.\nAdım 3: Zamanlayıcılar belirli aralıklarla tekrar eder ve \"ilk kez yeniden birlikte\" ifadesi EKOK'u gösterir.\nSık yapılan hata: \"Eşit\" sözcüğünü görüp EKOK demek. Eylem bölmekse EBOB, buluşmaksa EKOK.\nCevap C."
},
{
  id: "mat-ck-229",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Bir bilgi yarışmasında 51, 53, 57, 61, 63 ve 67 numaralı altı kart masaya dizilmiştir. Yarışmacı, üzerinde asal sayı yazan kartların sayısını bulacaktır.\n**Buna göre masadaki asal sayı yazan kart sayısı kaçtır?**",
  gorsel: null,
  secenekler: ["2","3","4","6"],
  dogru: 1,
  hatalar: ["Asal olan bir sayıyı (53, 61 ya da 67) bölünebilir sanıp eleme.",null,"3'e bölünmeyi kontrol etmeme: 51 = 3 · 17 olduğu hâlde 51'i asal sayma.","Altı sayıyı da tek sayı diye asal sanma; 51, 57 ve 63 asal değildir."],
  aciklama: "Asal sayı, 1 ve kendisinden başka pozitif böleni olmayan 1'den büyük sayıdır. 100'den küçük bir sayının asal olup olmadığını anlamak için 2, 3, 5 ve 7'ye bölünüp bölünmediğine bak.\nAdım 1: 51 → rakamları toplamı 6, 3'e bölünür (51 = 3 · 17). Asal değil.\nAdım 2: 57 → rakamları toplamı 12, 3'e bölünür. 63 → toplam 9, 3'e bölünür. İkisi de asal değil.\nAdım 3: 53, 61 ve 67 sayıları 2, 3, 5 ve 7'ye bölünmez; üçü de asaldır.\nSağlama: 7 ile deneme: 53 = 7 · 7 + 4, 61 = 7 · 8 + 5, 67 = 7 · 9 + 4; kalan hep sıfırdan farklı.\nSık yapılan hata: Her tek sayıyı asal saymak.\nCevap B."
},
{
  id: "mat-ck-230",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Okul bahçesindeki uzun bir merdivende üç sporcu, 0. basamaktan başlayarak yukarı çıkmaktadır. Ali her adımda 4, Burcu her adımda 6, Cem her adımda 10 basamak atlamaktadır. Üçünün de ayak bastığı ilk ortak basamak aranmaktadır; başlangıç olan 0. basamak sayılmayacaktır.\n**Buna göre bu basamağın numarası kaçtır?**",
  gorsel: null,
  secenekler: ["30","60","120","240"],
  dogru: 1,
  hatalar: ["30, 4'ün katı değildir: Ali 28. ve 32. basamaklara basar, 30. basamağa basmaz.",null,"120 ortak bir kattır ama en küçüğü değildir; 60. basamakta üçü de zaten buluşmuştur.","4 · 6 · 10 = 240 çarpımını EKOK sanma; çarpım ortak kattır ama en küçük ortak kat değildir."],
  aciklama: "Üç sporcunun da bastığı basamağın numarası 4'ün, 6'nın ve 10'un ortak katıdır. İlk ortak basamak için en küçük ortak kat (EKOK) aranır.\nAdım 1: 4 = 2^{2}, 6 = 2 · 3, 10 = 2 · 5.\nAdım 2: Her asal çarpanın en büyük üslüsünü al: 2^{2} · 3 · 5 = 60.\nSağlama: 60 : 4 = 15, 60 : 6 = 10, 60 : 10 = 6; üçü de kalansız bölünür ve 60'tan küçük böyle bir sayı yoktur.\nSık yapılan hata: Üç sayıyı çarpıp EKOK saymak. Çarpım her zaman ortak kattır ama sayılar ortak asal çarpan taşıyorsa en küçük olmaz.\nCevap B."
},
{
  id: "mat-ck-231",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Ece, sınıf panosunu süslemek için 120 sayısının pozitif tam sayı çarpanlarından yalnızca çift olanlarını seçecek ve her birini ayrı bir kartın üzerine yazacaktır.\n**Buna göre Ece kaç kart hazırlar?**",
  gorsel: null,
  secenekler: ["4","6","8","12"],
  dogru: 3,
  hatalar: ["Çift olanlar yerine tek çarpanları sayma: 1, 3, 5 ve 15 tek çarpanlardır, bunlar 4 tanedir.","5 çarpanını hesaba katmama: yalnızca 2 ve 3'ten kurulan çift çarpanlar 2, 4, 6, 8, 12 ve 24'tür; 10, 20, 30, 40, 60 ve 120 de çifttir.","Çarpan çiftlerinin sayısını (1 · 120, 2 · 60, … → 8 çift) çift çarpan sayısı sanma; 120'nin 16 çarpanı vardır ve soru yalnızca çift olanları istiyor.",null],
  aciklama: "Bir sayının çarpanı, o sayıyı kalansız bölen pozitif tam sayıdır. Çift bir çarpan en az bir tane 2 asal çarpanı taşır.\nAdım 1: 120 = 2^{3} · 3 · 5. Bütün çarpanların sayısı (3 + 1) · (1 + 1) · (1 + 1) = 16'dır.\nAdım 2: Tek çarpanlar 2'yi hiç içermeyen çarpanlardır; yalnızca 3 ve 5'ten kurulur: 1, 3, 5, 15. Bunlar (1 + 1) · (1 + 1) = 4 tanedir.\nAdım 3: Çift çarpan sayısı 16 − 4 = 12'dir.\nSağlama: Çift çarpanlar 2, 4, 6, 8, 10, 12, 20, 24, 30, 40, 60, 120 olup tam 12 tanedir.\nSık yapılan hata: Çarpan çiftlerinin sayısını (8) çarpan sayısı sanmak ya da tek çarpanları (4) saymak.\nCevap D."
},
{
  id: "mat-ck-232",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 2,
  soru: "Mert, defterine dört kesir yazmış ve bunlardan yalnızca birinin sadeleştirilemediğini fark etmiştir: [[24|45]], [[22|45]], [[28|49]] ve [[39|52]].\n**Buna göre sadeleştirilemeyen kesrin pay ile paydasının toplamı kaçtır?**",
  gorsel: null,
  secenekler: ["67","69","77","91"],
  dogru: 0,
  hatalar: [null,"24 ile 45'in ortak böleni 3'tür; kesir 3 ile sadeleşerek [[8|15]] olur. 69, sadeleşen bir kesrin pay ve payda toplamıdır.","28 ile 49'un ortak böleni 7'dir; kesir 7 ile sadeleşerek [[4|7]] olur. 77, sadeleşen bir kesrin pay ve payda toplamıdır.","39 ile 52'nin ortak böleni 13'tür; kesir 13 ile sadeleşerek [[3|4]] olur. 91, sadeleşen bir kesrin pay ve payda toplamıdır."],
  aciklama: "Bir kesrin sadeleşmemesi için pay ile paydanın aralarında asal olması, yani 1'den başka ortak asal çarpanlarının bulunmaması gerekir.\nAdım 1: 24 = 2^{3} · 3 ve 45 = 3^{2} · 5 → ortak asal çarpan 3. Sadeleşir.\nAdım 2: 28 = 2^{2} · 7 ve 49 = 7^{2} → ortak asal çarpan 7. Sadeleşir.\nAdım 3: 39 = 3 · 13 ve 52 = 2^{2} · 13 → ortak asal çarpan 13. Sadeleşir.\nAdım 4: 22 = 2 · 11 ve 45 = 3^{2} · 5 → ortak asal çarpan yok. [[22|45]] sadeleşmez ve toplam 22 + 45 = 67 olur.\nSık yapılan hata: Yalnızca 2, 3 ve 5 ile deneme yapıp 7 ya da 13 gibi ortak çarpanları kaçırmak; toplamı sadeleşen bir kesirden almak.\nCevap A."
},
{
  id: "mat-ck-233",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Bir kütüphaneci, 1'den 99'a kadar numaralanmış rafların arasından, numarası hem 9'a hem 12'ye tam bölünenleri kırmızı etiketle işaretlemiştir.\n**Buna göre kırmızı etiketli en büyük raf numarası kaçtır?**",
  gorsel: null,
  secenekler: ["36","54","72","96"],
  dogru: 2,
  hatalar: ["36, EKOK'tur ama kırmızı etiketli en büyük numara değildir; 72 de hem 9'a hem 12'ye bölünür.","54, 9'un katıdır ama 12'nin katı değildir (54 : 12 kalanlıdır).",null,"96, 12'nin katıdır ama 9'un katı değildir (96 : 9 kalanlıdır)."],
  aciklama: "Hem 9'a hem 12'ye tam bölünen sayılar, bu iki sayının ortak katlarıdır; yani EKOK'un katlarıdır.\nAdım 1: 9 = 3^{2} ve 12 = 2^{2} · 3. EKOK = 2^{2} · 3^{2} = 36.\nAdım 2: 36'nın katlarını yaz: 36, 72, 108… Bunlardan 99'u geçmeyenler 36 ve 72'dir.\nAdım 3: En büyüğü 72'dir.\nSağlama: 72 : 9 = 8 ve 72 : 12 = 6; ikisi de kalansız.\nSık yapılan hata: Yalnızca bir sayıya bölünmeye bakmak. 54 yalnızca 9'a, 96 yalnızca 12'ye bölünür.\nCevap C."
},
{
  id: "mat-ck-234",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Defne, asal çarpanları yalnızca 2 ve 5 olan (ikisini de içeren) iki basamaklı sayıları bir listeye yazmaktadır.\n**Buna göre listedeki en büyük sayı kaçtır?**",
  gorsel: null,
  secenekler: ["50","64","80","90"],
  dogru: 2,
  hatalar: ["2 · 5^{2} = 50 yazıp 2^{4} · 5 = 80'i unutma.","64 = 2^{6} yalnızca 2'yi çarpan olarak içerir; 5 çarpanı yoktur.",null,"90 = 2 · 3^{2} · 5 sayısında üçüncü bir asal çarpan olan 3 vardır."],
  aciklama: "Asal çarpanları yalnızca 2 ve 5 olan sayılar 2^{a} · 5^{b} biçimindedir (a ve b en az 1).\nAdım 1: 5'in üssü 1 iken: 2 · 5 = 10, 2^{2} · 5 = 20, 2^{3} · 5 = 40, 2^{4} · 5 = 80. Sıradaki 2^{5} · 5 = 160 üç basamaklıdır.\nAdım 2: 5'in üssü 2 iken: 2 · 5^{2} = 50. Sıradaki 2^{2} · 5^{2} = 100 üç basamaklıdır.\nAdım 3: İki basamaklı olanlar 10, 20, 40, 50 ve 80'dir; en büyüğü 80'dir.\nSık yapılan hata: Şıklardaki sayıların asal çarpanlarını kontrol etmemek. 64'te 5, 90'da 3 vardır.\nCevap C."
},
{
  id: "mat-ck-235",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Boyları 45 m ve 75 m olan iki halat, hiç artmayacak biçimde, eşit uzunlukta ve olabildiğince uzun parçalara kesilecektir.\n**Buna göre bu iş için toplam kaç kesim yapılır?**",
  gorsel: null,
  secenekler: ["6","8","15","120"],
  dogru: 0,
  hatalar: [null,"Parça sayısını (3 + 5 = 8) kesim sayısı sanma; n parça için n − 1 kesim gerekir.","EBOB'u, yani parçanın uzunluğunu cevap sanma.","İki halatın uzunluklarını toplama (45 + 75 = 120)."],
  aciklama: "Parçalar eşit, artmayan ve en uzun olacağı için parça uzunluğu EBOB'dur.\nAdım 1: 45 = 3^{2} · 5 ve 75 = 3 · 5^{2}. EBOB = 3 · 5 = 15 m.\nAdım 2: Parça sayıları: 45 : 15 = 3 ve 75 : 15 = 5.\nAdım 3: 3 parça için 2 kesim, 5 parça için 4 kesim gerekir: 2 + 4 = 6.\nSağlama: Halatın ucuna kesim yapılmaz; n parça n − 1 kesimle elde edilir.\nSık yapılan hata: Parça sayısı (8) ile kesim sayısını karıştırmak.\nCevap A."
},
{
  id: "mat-ck-236",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Bir bulmacada, pozitif tam sayı çarpanlarının sayısı tam 3 olan en küçük iki basamaklı doğal sayı aranmaktadır.\n**Buna göre aranan sayı kaçtır?**",
  gorsel: null,
  secenekler: ["11","16","25","49"],
  dogru: 2,
  hatalar: ["11 asaldır; yalnızca 2 çarpanı vardır (1 ve 11).","16'nın 5 çarpanı vardır: 1, 2, 4, 8, 16.",null,"49 da tam 3 çarpanlıdır ama en küçük değildir; 25 daha küçüktür."],
  aciklama: "Çarpanları 1, bir asal sayı ve o asalın karesi olan sayıların tam 3 çarpanı vardır. Yani sayı, bir asal sayının karesidir.\nAdım 1: Asal sayıların karelerini yaz: 2^{2} = 4, 3^{2} = 9, 5^{2} = 25, 7^{2} = 49.\nAdım 2: İki basamaklı olanlar 25 ve 49'dur. En küçüğü 25'tir.\nSağlama: 25'in çarpanları 1, 5 ve 25'tir; tam üç tane.\nSık yapılan hata: İki çarpanlı asal sayı (11) ya da çok çarpanlı 16 gibi sayıları seçmek.\nCevap C."
},
{
  id: "mat-ck-237",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 2,
  soru: "Bir matematik etkinliğinde dört öğrenciye birer sayı çifti verilmiştir. Bu çiftlerden yalnızca biri aralarında asal değildir. Öğrencilerin çiftleri tabloda gösterilmiştir.\n**Buna göre aralarında asal olmayan çiftin EBOB'u kaçtır?**",
  gorsel: "<table class=\"tablo\"><tr><th>Öğrenci</th><th>Birinci sayı</th><th>İkinci sayı</th></tr><tr><td>Aslı</td><td>8</td><td>27</td></tr><tr><td>Berk</td><td>15</td><td>32</td></tr><tr><td>Can</td><td>35</td><td>36</td></tr><tr><td>Derya</td><td>33</td><td>55</td></tr></table>",
  secenekler: ["1","3","5","11"],
  dogru: 3,
  hatalar: ["Aralarında asal olan bir çiftin EBOB'unu alma: Aslı, Berk ve Can'ın çiftlerinde EBOB 1'dir; aranan çift bunlar değildir.","3, 33'ün bir çarpanıdır ama 55'i bölmez; ortak bölen değildir.","5, 55'in bir çarpanıdır ama 33'ü bölmez; ortak bölen değildir.",null],
  aciklama: "Aralarında asal sayıların 1'den başka ortak böleni yoktur. Önce 1'den büyük ortak böleni olan çifti bul, sonra o çiftin EBOB'unu hesapla.\nAdım 1: 8 = 2^{3} ve 27 = 3^{3} → ortak asal yok. 15 = 3 · 5 ve 32 = 2^{5} → ortak asal yok. 35 = 5 · 7 ve 36 = 2^{2} · 3^{2} → ortak asal yok (ardışık sayılar).\nAdım 2: 33 = 3 · 11 ve 55 = 5 · 11 → ortak asal çarpan 11. Aralarında asal olmayan çift Derya'nın çiftidir.\nAdım 3: EBOB(33, 55) = 11.\nSağlama: 33 : 11 = 3 ve 55 : 11 = 5; 3 ile 5'in ortak böleni yoktur, yani 11 en büyük ortak bölendir.\nSık yapılan hata: Çiftin bir sayısının çarpanını (3 ya da 5) ortak bölen sanmak. Ortak bölen iki sayıyı da bölmelidir.\nCevap D."
},
{
  id: "mat-ck-238",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Bir saat atölyesinde, dişli sayıları 12 ve 18 olan iki çark birbirine geçmiş hâlde dönmektedir. Başlangıçta her çarkın işaretli bir dişi birbirine değmektedir. Çarklar dönmeye başladıktan sonra işaretli dişler ilk kez yeniden bu konumda buluşacaktır.\n**Buna göre bu ana kadar 18 dişli çark kaç tur atmış olur?**",
  gorsel: null,
  secenekler: ["2","3","6","36"],
  dogru: 0,
  hatalar: [null,"12 dişli çarkın tur sayısını (3) bulma; soru 18 dişli çarkın turunu istiyor.","EBOB(12, 18) = 6'yı cevap sanma; yeniden buluşma EBOB ile değil EKOK ile bulunur.","EKOK'u (36 diş) tur sayısı sanma; 36, buluşana kadar geçen diş sayısıdır, tur değil."],
  aciklama: "İşaretli dişler yeniden buluştuğunda iki çarktan da aynı sayıda diş geçmiştir; bu sayı 12 ile 18'in ortak katıdır. İlk buluşma için EKOK aranır.\nAdım 1: 12 = 2^{2} · 3 ve 18 = 2 · 3^{2}. EKOK = 2^{2} · 3^{2} = 36 diş.\nAdım 2: 18 dişli çark 36 : 18 = 2 tur atar.\nSağlama: 12 dişli çark 36 : 12 = 3 tur atar; ikisi de tam tur olduğundan işaretli dişler yeniden karşılaşır.\nSık yapılan hata: EKOK'u (36) tur sayısı sanmak ya da hangi çarkın sorulduğunu atlamak.\nCevap A."
},
{
  id: "mat-ck-239",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Aşağıdaki tabloda dört kartın üzerindeki sayıların asal çarpanlarına ayrılmış biçimleri verilmiştir.\n**Buna göre pozitif tam sayı çarpanlarının sayısı en fazla olan kart hangisidir?**",
  gorsel: "<table class=\"tablo\"><tr><th>Kart</th><th>Asal çarpanlarına ayrılmış biçimi</th></tr><tr><td>Mavi</td><td>2<sup>2</sup> · 3<sup>2</sup></td></tr><tr><td>Kırmızı</td><td>2 · 3 · 5</td></tr><tr><td>Yeşil</td><td>2<sup>5</sup></td></tr><tr><td>Sarı</td><td>3 · 5<sup>2</sup></td></tr></table>",
  secenekler: ["Kırmızı","Yeşil","Sarı","Mavi"],
  dogru: 3,
  hatalar: ["Farklı asal çarpanı en çok olan kartı seçme; Kırmızı'nın 8 çarpanı vardır, Mavi'nin 9.","Üssü en büyük olan kartı seçme; 2^{5} sayısının yalnızca 6 çarpanı vardır.","Değeri en büyük olan kartı (75) seçme; çarpan sayısı değerle ilgili değildir, Sarı'nın 6 çarpanı vardır.",null],
  aciklama: "Asal çarpanlarına ayrılmış biçimde üsleri birer artırıp çarparsan çarpan sayısını bulursun.\nAdım 1: Mavi: (2 + 1) · (2 + 1) = 9 çarpan.\nAdım 2: Kırmızı: (1 + 1) · (1 + 1) · (1 + 1) = 8 çarpan.\nAdım 3: Yeşil: 5 + 1 = 6 çarpan. Sarı: (1 + 1) · (2 + 1) = 6 çarpan.\nAdım 4: En fazla çarpan Mavi kartta (9) bulunur.\nSağlama: Mavi kart 36'dır; çarpanları 1, 2, 3, 4, 6, 9, 12, 18, 36 olmak üzere 9 tanedir.\nSık yapılan hata: Sayının büyüklüğüne (Sarı 75) ya da üssün büyüklüğüne (Yeşil) bakmak.\nCevap D."
},
{
  id: "mat-ck-240",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Zeynep, matematik defterine 36 ile 48 sayılarını birlikte kalansız bölen bütün pozitif tam sayıları yazıp bunları toplayacaktır. Önce bu sayıları bulacak, sonra toplayacaktır.\n**Buna göre Zeynep'in bulacağı toplam kaçtır?**",
  gorsel: null,
  secenekler: ["16","28","84","91"],
  dogru: 1,
  hatalar: ["Listede EBOB'u (12) unutma: 1 + 2 + 3 + 4 + 6 = 16 olur; 12 de ortak bölendir.",null,"36 ile 48 sayılarının kendilerini toplama (36 + 48 = 84); soru ortak bölenlerin toplamını istiyor.","Yalnızca 36'nın bütün bölenlerini toplama (1 + 2 + 3 + 4 + 6 + 9 + 12 + 18 + 36 = 91); 9, 18 ve 36 sayıları 48'i bölmez."],
  aciklama: "İki sayının ortak bölenleri, EBOB'un bölenleridir.\nAdım 1: 36 = 2^{2} · 3^{2} ve 48 = 2^{4} · 3. Ortak asallar 2 ve 3; küçük üsler: EBOB = 2^{2} · 3 = 12.\nAdım 2: 12'nin bölenleri 1, 2, 3, 4, 6 ve 12'dir. Bunların her biri 36'yı da 48'i de kalansız böler.\nAdım 3: Toplam 1 + 2 + 3 + 4 + 6 + 12 = 28.\nSağlama: 9, 18 ve 36 sayıları 36'yı böler ama 48'i bölmez; listeye giremez.\nSık yapılan hata: EBOB'u (12) listeye almayı unutmak (16) ya da yalnızca bir sayının bölenlerini toplamak (91).\nCevap B."
},
{
  id: "mat-ck-241",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Bir kodlama oyununda anahtar sayı, asal çarpanlarına ayrılmış biçimi 2^{3} · 3^{2} · 5 olan sayıdır. Oyunun kartlarında bu sayıyla ilgili dört sayı yazılıdır.\n**Buna göre aşağıdaki kart sayılarından hangisi anahtar sayının çarpanı __değildir__?**",
  gorsel: null,
  secenekler: ["72","90","120","240"],
  dogru: 3,
  hatalar: ["72 = 2^{3} · 3^{2} sayısında hiçbir üs anahtar sayıdakini aşmaz; 360 : 72 = 5 olduğundan 72 bir çarpandır.","90 = 2 · 3^{2} · 5 sayısında üsler küçük ya da eşittir; 360 : 90 = 4 olduğundan 90 bir çarpandır.","120 = 2^{3} · 3 · 5 sayısında üsler anahtar sayıdakini aşmaz; 360 : 120 = 3 olduğundan 120 bir çarpandır.",null],
  aciklama: "Bir sayının çarpanı, o sayının asal çarpanlarından oluşur ve hiçbir asalın üssü sayıdakinden büyük olamaz.\nAdım 1: Anahtar sayı 2^{3} · 3^{2} · 5 = 360'tır. Bir çarpanda 2'nin üssü en çok 3, 3'ün üssü en çok 2, 5'in üssü en çok 1 olabilir.\nAdım 2: 72 = 2^{3} · 3^{2}, 90 = 2 · 3^{2} · 5 ve 120 = 2^{3} · 3 · 5; üsler sınırları aşmıyor, üçü de çarpandır.\nAdım 3: 240 = 2^{4} · 3 · 5; 2'nin üssü 4'tür ve anahtar sayıdaki 3'ü aşar. 240 çarpan değildir.\nSağlama: 360 : 240 = 1,5; kalansız bölünmez.\nSık yapılan hata: Yalnızca asalların aynı olmasına bakıp üsleri denetlememek. 240'ta da 2, 3 ve 5 var ama 2'nin üssü fazla.\nCevap D."
},
{
  id: "mat-ck-242",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 2,
  soru: "Bir oyunda toplamları 20 olan iki farklı pozitif tam sayıdan oluşan kart çiftleri hazırlanacaktır. Her çiftteki iki sayı aralarında asal olacaktır. Aynı iki sayıdan oluşan çiftler sırası önemsenmeden bir kez sayılacaktır.\n**Buna göre kaç farklı kart çifti hazırlanabilir?**",
  gorsel: null,
  secenekler: ["2","4","5","9"],
  dogru: 1,
  hatalar: ["Yalnızca iki asal sayıdan oluşan çiftleri (3 ve 17, 7 ve 13) sayma; 1 ve 19 ile 9 ve 11 de aralarında asaldır.",null,"5 ve 15 çiftini kontrol etmeme; ikisi de 5'e bölünür.","Toplamı 20 olan bütün çiftleri sayma; aralarında asal olma koşulu uygulanmamış."],
  aciklama: "Toplamı 20 olan çiftleri yaz, sonra her birinin ortak böleni var mı diye bak.\nAdım 1: Çiftler: (1, 19), (2, 18), (3, 17), (4, 16), (5, 15), (6, 14), (7, 13), (8, 12), (9, 11).\nAdım 2: Çift sayılardan oluşan çiftler (2-18, 4-16, 6-14, 8-12) ortak bölen 2 taşır; elenir. (5, 15) ortak bölen 5 taşır; elenir.\nAdım 3: Kalanlar (1, 19), (3, 17), (7, 13), (9, 11); hepsinin ortak böleni yalnızca 1'dir.\nSağlama: 9 = 3^{2} ve 11 asaldır; ortak asal çarpan yok.\nSık yapılan hata: Yalnızca asal sayılardan oluşan çiftleri saymak. 9 asal değildir ama 11 ile aralarında asaldır.\nCevap B."
},
{
  id: "mat-ck-243",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Bir atölyedeki iki zamanlayıcıdan biri 40 saniyede bir, diğeri 60 saniyede bir sesli uyarı vermektedir. İkisi aynı anda başlatılmıştır; başlatıldığı an uyarı sayılmayacaktır.\n**Buna göre iki zamanlayıcı başlatıldıktan sonraki ilk 5 dakikada kaç kez aynı anda uyarı verir?**",
  gorsel: null,
  secenekler: ["2","3","5","7"],
  dogru: 0,
  hatalar: [null,"Başlatılma anını (0. saniye) da sayma; bu an uyarı olarak sayılmayacaktır.","300 : 60 işlemini yapıp yalnızca 60 saniyelik zamanlayıcının uyarı sayısını bulma.","300 : 40 işleminin bölümünü alıp yalnızca 40 saniyelik zamanlayıcının uyarı sayısını bulma."],
  aciklama: "İki zamanlayıcının aynı anda uyarı verdiği anlar, 40 ile 60'ın ortak katı olan saniyelerdir.\nAdım 1: 40 = 2^{3} · 5 ve 60 = 2^{2} · 3 · 5. EKOK = 2^{3} · 3 · 5 = 120 saniye.\nAdım 2: 5 dakika = 300 saniye. Ortak anlar 120. ve 240. saniyelerdir; 360. saniye 300'ü aşar.\nAdım 3: İki ortak an vardır: 2 kez.\nSağlama: 120 saniyede birinci zamanlayıcı 3, ikincisi 2 kez uyarı vermiştir; 240 saniyede 6 ve 4 kez.\nSık yapılan hata: Başlangıç anını saymak (3). Soruda başlangıç anının sayılmayacağı yazıyor.\nCevap A."
},
{
  id: "mat-ck-244",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Bir okulun gösterisinde 48 balon, her torbada eşit sayıda balon olacak ve hiçbir balon açıkta kalmayacak biçimde torbalara konulacaktır. Torba sayısı çift sayı olacaktır.\n**Buna göre torba sayısı kaç farklı değer alabilir?**",
  gorsel: null,
  secenekler: ["5","6","7","8"],
  dogru: 3,
  hatalar: ["2, 4, 6, 8, 12 değerlerini yazıp 16, 24 ve 48'i unutma.","Çarpan çiftlerinden 16 ve 48'i atlama.","48 torbayı olamaz sanma; 48 torbada her torbaya 1 balon düşer, bu da koşula uyar.",null],
  aciklama: "Torba sayısı hem 48'in çarpanı hem de çift olmalıdır.\nAdım 1: 48'in çarpan çiftleri: 1 · 48, 2 · 24, 3 · 16, 4 · 12, 6 · 8. Çarpanlar: 1, 2, 3, 4, 6, 8, 12, 16, 24, 48.\nAdım 2: Çift olanları seç: 2, 4, 6, 8, 12, 16, 24, 48.\nAdım 3: Say: 8 farklı değer.\nSağlama: 48 = 2^{4} · 3 olduğundan çarpan sayısı 5 · 2 = 10; tek olanlar 1 ve 3'tür, geriye 8 çift çarpan kalır.\nSık yapılan hata: Çarpanları eksik yazmak. Çiftler hâlinde yazarsan hiçbirini atlamazsın.\nCevap D."
},
{
  id: "mat-ck-245",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 2,
  soru: "Bir kodlama yarışmasında, aralarında asal olan iki doğal sayıdan oluşan bir kart çifti aranmaktadır. Çiftin EKOK'u 140'tır ve sayılardan biri 20'dir.\n**Buna göre diğer sayı kaçtır?**",
  gorsel: null,
  secenekler: ["7","14","28","35"],
  dogru: 0,
  hatalar: [null,"EKOK(20, 14) = 140 olur ama 20 ile 14'ün ortak böleni 2'dir; aralarında asal değiller.","EKOK(20, 28) = 140 olur ama 20 ile 28'in ortak böleni 4'tür; aralarında asal değiller.","EKOK(20, 35) = 140 olur ama 20 ile 35'in ortak böleni 5'tir; aralarında asal değiller."],
  aciklama: "Aralarında asal iki sayının EKOK'u, çarpımlarına eşittir (çünkü EBOB 1'dir).\nAdım 1: Diğer sayıya x de: 20 · x = 140, yani x = 7.\nAdım 2: Kontrol et: 20 = 2^{2} · 5 ve 7 asaldır; ortak asal çarpan yok, aralarında asaldırlar.\nAdım 3: 14, 28 ve 35 de EKOK'u 140 yapar ama bunların her biri 20 ile ortak bir asal çarpan taşır; EBOB'ları 2, 4 ve 5'tir.\nSağlama: 20 · 7 = 140 ve EBOB(20, 7) = 1.\nSık yapılan hata: Yalnızca EKOK koşuluna bakıp aralarında asal olma koşulunu denetlememek.\nCevap A."
},
{
  id: "mat-ck-246",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Bir kantinde simit 6 liradan, poğaça 8 liradan satılmaktadır. Selin yalnızca simit, Kerem yalnızca poğaça alacak ve ikisi de en az birer ürün alacaktır. İkisinin ödeyeceği tutar birbirine eşit olacaktır.\n**Buna göre her birinin ödeyeceği en az tutar kaç liradır?**",
  gorsel: null,
  secenekler: ["2","14","24","48"],
  dogru: 2,
  hatalar: ["EBOB(6, 8) = 2'yi alma; eşit tutar için ortak kat gerekir.","6 + 8 = 14 fiyatları toplama; 14, 6'nın katı değildir.",null,"6 · 8 = 48'i alma; 48 ortak kattır ama en küçük ortak kat değildir."],
  aciklama: "Selin'in ödeyeceği tutar 6'nın katı, Kerem'in ödeyeceği tutar 8'in katı olmalıdır ve iki tutar eşittir. Yani tutar 6 ile 8'in ortak katıdır; en az tutar için EKOK aranır.\nAdım 1: 6 = 2 · 3 ve 8 = 2^{3}. EKOK = 2^{3} · 3 = 24.\nAdım 2: Selin 24 : 6 = 4 simit, Kerem 24 : 8 = 3 poğaça alır; ikisi de 24 lira öder.\nSağlama: 24'ten küçük hiçbir sayı hem 6'nın hem 8'in katı değildir (6, 12 ve 18 sekizin katı değil).\nSık yapılan hata: Fiyatları toplamak (14) ya da EBOB'u almak (2). Eşit tutar, ortak kat demektir.\nCevap C."
},
{
  id: "mat-ck-247",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 2,
  soru: "Bir manav 56 elmayı, her kasada eşit sayıda elma olacak ve hiç elma açıkta kalmayacak biçimde kasalara koyacaktır. Bir kasaya en az 3, en fazla 10 elma konulabilmektedir.\n**Buna göre manav kaç farklı kasa sayısı kullanabilir?**",
  gorsel: null,
  secenekler: ["2","3","4","8"],
  dogru: 1,
  hatalar: ["Koşula uyan değerlerden birini (örneğin 7 elmalık kasayı) atlama.",null,"14 elmalık kasayı da sayma; bir kasaya en fazla 10 elma konulabilir.","56'nın bütün çarpanlarını sayma; elma sayısı koşulu uygulanmamış."],
  aciklama: "Bir kasadaki elma sayısı 56'yı kalansız bölmelidir ve 3 ile 10 arasında (uçlar dahil) olmalıdır. Her uygun elma sayısına tek bir kasa sayısı karşılık gelir.\nAdım 1: 56'nın çarpan çiftleri: 1 · 56, 2 · 28, 4 · 14, 7 · 8. Çarpanlar: 1, 2, 4, 7, 8, 14, 28, 56.\nAdım 2: 3 ile 10 arasında kalanlar 4, 7 ve 8'dir.\nAdım 3: Bunlara karşılık kasa sayıları 14, 8 ve 7'dir; 3 farklı değer.\nSağlama: 14 · 4 = 56, 8 · 7 = 56, 7 · 8 = 56.\nSık yapılan hata: Koşulu uygulamadan bütün çarpanları saymak (8).\nCevap B."
},
{
  id: "mat-ck-248",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "İki doğal sayının çarpımı 300'dür. Bu sayıların EBOB'u 5, EKOK'u 60'tır ve sayılardan biri 15'tir.\n**Buna göre diğer sayı kaçtır?**",
  gorsel: null,
  secenekler: ["4","12","15","20"],
  dogru: 3,
  hatalar: ["60 : 15 işlemini yapıp diğer sayıyı bulduğunu sanma; EKOK, sayıların çarpımının EBOB'a bölümüdür.","EKOK : EBOB = 12'yi diğer sayı sanma.","Verilen sayının kendisini bulma; EBOB(15, 15) = 15 olur, 5 değil.",null],
  aciklama: "İki sayının çarpımı, EBOB'ları ile EKOK'larının çarpımına eşittir.\nAdım 1: 15 · x = 5 · 60 = 300 → x = 300 : 15 = 20.\nSağlama: 15 = 3 · 5 ve 20 = 2^{2} · 5. EBOB = 5, EKOK = 2^{2} · 3 · 5 = 60. Verilenlerle uyuşuyor.\nSık yapılan hata: EKOK'u verilen sayıya bölerek diğer sayıyı bulmaya çalışmak. Doğru bağıntı: çarpım = EBOB · EKOK.\nCevap D."
},
{
  id: "mat-ck-249",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Bir fidanlıkta, sayısı 100'den fazla olan fidanlar 5'erli sıralara dizildiğinde 3 fidan, 8'erli sıralara dizildiğinde de 3 fidan açıkta kalmaktadır. Fidan sayısı, bu özelliğe sahip olan 100'den fazla en küçük sayıdır.\n**Buna göre fidanlıkta kaç fidan vardır?**",
  gorsel: null,
  secenekler: ["43","83","120","123"],
  dogru: 3,
  hatalar: ["43 de 5'erli ve 8'erli dizilince 3 artar ama 100'den fazla koşulunu sağlamaz.","83 de 5'erli ve 8'erli dizilince 3 artar ama 100'den küçüktür.","EKOK'un katını alıp artan 3 fidanı eklemeyi unutma.",null],
  aciklama: "Fidan sayısından 3 çıkarılırsa sayı hem 5'e hem 8'e tam bölünür; yani 3 çıkarılmış sayı EKOK'un katıdır.\nAdım 1: EKOK(5, 8) = 40 (5 ve 8 aralarında asal). Fidan sayısı \"40'ın bir katı + 3\" biçimindedir: 43, 83, 123, 163…\nAdım 2: 100'den fazla en küçük değer 123'tür.\nSağlama: 123 = 5 · 24 + 3 ve 123 = 8 · 15 + 3. İki dizilişte de 3 fidan artar.\nSık yapılan hata: EKOK'un katını bulunca artanı eklemeyi unutmak (120) ya da 100'ün altında kalan değeri almak (83).\nCevap D."
},
{
  id: "mat-ck-250",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Bir bilgisayar oyununda iki kapının şifreleri, asal çarpanlarına ayrılmış biçimleriyle A = 2^{3} · 3^{2} · 5 ve B = 2^{2} · 3^{4} · 7 olarak verilmiştir. Oyuncu, A ile B sayılarını birlikte kalansız bölen kaç farklı pozitif tam sayı olduğunu girerse kapılar açılacaktır.\n**Buna göre oyuncunun girmesi gereken sayı kaçtır?**",
  gorsel: null,
  secenekler: ["9","20","24","36"],
  dogru: 0,
  hatalar: [null,"Büyük üsleri alıp (2^{3} · 3^{4}) onun çarpan sayısını bulma (4 · 5 = 20); bu EKOK mantığıdır, ortak bölen için küçük üsler alınır.","Yalnızca A'nın çarpan sayısını bulma: (3 + 1) · (2 + 1) · (1 + 1) = 24; B'ye bölünme koşulu uygulanmamış.","EBOB'un değerini (36) cevap sanma; soru ortak bölenlerin kaç tane olduğunu soruyor."],
  aciklama: "Ortak bölenler EBOB'un bölenleridir. Önce EBOB'u bul, sonra çarpan sayısını hesapla.\nAdım 1: Ortak asallar 2 ve 3'tür; 5 yalnızca A'da, 7 yalnızca B'dedir. Küçük üsler: 2^{2} ve 3^{2}.\nAdım 2: EBOB = 2^{2} · 3^{2} = 36.\nAdım 3: Çarpan sayısı (2 + 1) · (2 + 1) = 9.\nSağlama: 36'nın bölenleri 1, 2, 3, 4, 6, 9, 12, 18, 36 olmak üzere 9 tanedir ve her biri hem A'yı hem B'yi böler.\nSık yapılan hata: Büyük üsleri almak (20) ya da EBOB'un değerini (36) cevap sanmak.\nCevap A."
},
{
  id: "mat-ck-251",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 2,
  soru: "Uzunlukları 84 m ve 120 m olan iki paralel yürüyüş yolunun her birinin iki ucuna da fidan dikilecek, yol boyunca fidanlar eşit aralıklarla dizilecektir. Aralık metre cinsinden bir tam sayıdır, iki yolda da aynıdır ve olabildiğince büyüktür.\n**Buna göre iki yola toplam kaç fidan dikilir?**",
  gorsel: null,
  secenekler: ["12","17","18","19"],
  dogru: 3,
  hatalar: ["EBOB'u, yani aralığı cevap sanma.","Her yolda aralık sayısını (7 ve 10) bulup uçlar için 1 eklemeyi unutma.","Yalnızca 84 m'lik yola 1 ekleyip 120 m'lik yola eklemeyi unutma: 8 + 10 = 18.",null],
  aciklama: "Aralığın iki yolu da tam bölmesi ve en büyük olması için aralık, EBOB'dur.\nAdım 1: 84 = 2^{2} · 3 · 7 ve 120 = 2^{3} · 3 · 5. EBOB = 2^{2} · 3 = 12 m.\nAdım 2: Aralık sayıları: 84 : 12 = 7 ve 120 : 12 = 10.\nAdım 3: İki ucuna da fidan dikilen açık bir yolda fidan sayısı aralık sayısından 1 fazladır: 7 + 1 = 8 ve 10 + 1 = 11.\nAdım 4: Toplam 8 + 11 = 19 fidan.\nSık yapılan hata: Uçlara dikilen fidanı saymamak. Açık yolda fidan sayısı = aralık sayısı + 1.\nCevap D."
},
{
  id: "mat-ck-252",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Bir güvenlik programı kapı şifresini şu kuralla üretir: Kapı numarası iki asal sayının çarpımı olarak yazılır ve şifre bu iki asal sayının toplamıdır. Örneğin 21 = 3 · 7 numaralı kapının şifresi 3 + 7 = 10'dur. Aynı kuralla 15 = 3 · 5 numaralı kapının şifresi 8, 35 = 5 · 7 numaralı kapının şifresi 12 olarak üretilmektedir.\n**Buna göre 143 numaralı kapının şifresi kaçtır?**",
  gorsel: null,
  secenekler: ["22","24","26","144"],
  dogru: 1,
  hatalar: ["143 = 11 · 11 sanma; 11 · 11 = 121 eder, 143 etmez.",null,"143 = 13 · 13 sanma; 13 · 13 = 169 eder, 143 etmez.","1 ve 143 çiftini alma; 1 asal değildir, 143 de asal değildir."],
  aciklama: "Kuralın çalışması için 143 sayısını iki asal sayının çarpımı olarak yazmalısın. Bunun için küçük asal sayılardan başlayarak böl.\nAdım 1: 143 tek sayıdır (2 yok), rakamları toplamı 8'dir (3 yok), sonu 3'tür (5 yok).\nAdım 2: 7 ile dene: 7 · 20 = 140 ve kalan 3'tür; 7'ye bölünmez.\nAdım 3: 11 ile dene: 11 · 13 = 143. İki çarpan da asaldır.\nAdım 4: Şifre 11 + 13 = 24 olur.\nSağlama: 11 · 13 = 143.\nSık yapılan hata: Bölenleri denerken 7'de durup 143'ü asal sanmak ya da 1 ile 143 çiftini almak.\nCevap B."
},
{
  id: "mat-ck-253",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Bir çiçekçi, sardunyaları 3 günde bir, menekşeleri 4 günde bir sulamaktadır. Mayıs ayının 1'inde ikisini de sulamış ve düzenini ay boyunca değiştirmemiştir. Çiçekçi, aynı gün hem sardunyaları hem menekşeleri sulamasına \"çifte sulama\" demektedir. 1 Mayıs da bir çifte sulama günüdür ve Mayıs ayı 31 gündür.\n**Buna göre çiçekçi Mayıs ayında kaç kez çifte sulama yapmıştır?**",
  gorsel: null,
  secenekler: ["3","4","10","31"],
  dogru: 0,
  hatalar: [null,"Bölümü yuvarlayıp (31 : 12 → 3) başlangıç gününü bir kez daha ekleme.","31 : 3 = 10 bölümünü alıp yalnızca sardunya sulama sayısına bakma.","Ayın gün sayısını cevap sanma."],
  aciklama: "Çifte sulama günleri, 1 Mayıs'tan sonra hem 3'ün hem 4'ün katı kadar gün geçen günlerdir; yani EKOK aralığıyla tekrar eder.\nAdım 1: EKOK(3, 4) = 12 (3 ve 4 aralarında asaldır). Çifte sulama 12 günde bir yapılır.\nAdım 2: Günleri yaz: 1 Mayıs, 13 Mayıs, 25 Mayıs. Bir sonraki 37 olurdu; ay 31 gündür.\nAdım 3: Başlangıç günü dahil toplam 3 gün.\nSağlama: Sardunya 1, 4, 7, 10, 13, … 25; menekşe 1, 5, 9, 13, 17, 21, 25, 29. Ortak günler 1, 13 ve 25'tir.\nSık yapılan hata: Başlangıç gününü saymamak ya da iki kez saymak. Günleri tek tek yazarak denetle.\nCevap A."
},
{
  id: "mat-ck-254",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Bir kitap kulübünde Elif'in kartında A = 2^{3} · 3, Ali'nin kartında B = 2 · 3^{2} · 5 sayısı yazmaktadır. Kulüp başkanı iki kartı çarpmış ve çıkan sayının pozitif tam sayı çarpanlarının sayısını sormuştur. Elif ve Ali, çarpma işlemini yapmadan, sayıların asal çarpanlarına ayrılmış biçimlerinden yararlanarak cevabı bulmaya çalışmaktadır.\n**Buna göre A · B sayısının kaç pozitif tam sayı çarpanı vardır?**",
  gorsel: null,
  secenekler: ["12","20","24","40"],
  dogru: 3,
  hatalar: ["Yalnızca B'nin çarpan sayısını bulma: (1 + 1) · (2 + 1) · (1 + 1) = 12.","A'nın ve B'nin çarpan sayılarını toplama: 8 + 12 = 20.","Büyük üsleri alarak EKOK'un çarpan sayısını bulma: 2^{3} · 3^{2} · 5 için 4 · 3 · 2 = 24.",null],
  aciklama: "Aynı tabanlı üslü ifadeler çarpılırken üsler toplanır. Çarpan sayısı ise üsleri birer artırıp çarparak bulunur.\nAdım 1: A · B = 2^{3} · 3 · 2 · 3^{2} · 5 = 2^{4} · 3^{3} · 5.\nAdım 2: Çarpan sayısı = (4 + 1) · (3 + 1) · (1 + 1) = 5 · 4 · 2 = 40.\nSağlama: A = 24, B = 90 ve A · B = 2160 = 16 · 27 · 5 = 2^{4} · 3^{3} · 5.\nSık yapılan hata: Çarpanların sayısını ayrı ayrı bulup çarpmak (8 · 12 = 96) ya da toplamak (20). Önce çarpımı asal çarpanlarına ayır, sonra say.\nCevap D."
},
{
  id: "mat-ck-255",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 3,
  soru: "Bir bilgisayar oyunu, ekrana gelen sayı çiftlerinden aralarında asal olanlar için puan vermektedir. Oyun yalnızca iki sayının ortak böleninin olup olmadığına bakmakta, sayıların asal olup olmamasını dikkate almamaktadır. Oyunun bir turunda ekrana gelen altı sayı çifti aşağıdaki tabloda gösterilmiştir.\n**Buna göre bu turda kaç çift puan getirmiştir?**",
  gorsel: "<table class=\"tablo\"><tr><th>Çift</th><th>Birinci sayı</th><th>İkinci sayı</th></tr><tr><td>1</td><td>18</td><td>35</td></tr><tr><td>2</td><td>26</td><td>39</td></tr><tr><td>3</td><td>34</td><td>51</td></tr><tr><td>4</td><td>35</td><td>48</td></tr><tr><td>5</td><td>42</td><td>65</td></tr><tr><td>6</td><td>46</td><td>69</td></tr></table>",
  secenekler: ["3","4","5","6"],
  dogru: 0,
  hatalar: [null,"3. çiftin ortak böleni 17'yi görememe: 34 = 2 · 17 ve 51 = 3 · 17.","Hem 3. hem 6. çiftin ortak bölenini (17 ve 23) görememe.","Biri çift biri tek olan her çifti aralarında asal sanma; bu tablodaki çiftlerin hepsi böyledir ama 13, 17 ve 23 ortak bölen olur."],
  aciklama: "Aralarında asal iki sayının 1'den başka ortak asal çarpanı yoktur. Her çifti asal çarpanlarına ayırarak denetle.\nAdım 1: 18 = 2 · 3^{2}, 35 = 5 · 7 → ortak asal yok. Puan var.\nAdım 2: 26 = 2 · 13, 39 = 3 · 13 → ortak asal 13. Puan yok.\nAdım 3: 34 = 2 · 17, 51 = 3 · 17 → ortak asal 17. Puan yok.\nAdım 4: 35 = 5 · 7, 48 = 2^{4} · 3 → ortak asal yok. Puan var.\nAdım 5: 42 = 2 · 3 · 7, 65 = 5 · 13 → ortak asal yok. Puan var.\nAdım 6: 46 = 2 · 23, 69 = 3 · 23 → ortak asal 23. Puan yok.\nPuan getiren çiftler 1., 4. ve 5. çiftlerdir: 3 çift.\nSık yapılan hata: Yalnızca 2, 3, 5 ve 7 ile deneme yapıp 13, 17, 23 gibi büyük ortak çarpanları kaçırmak.\nCevap A."
},
{
  id: "mat-ck-256",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Bir belediye, parkın yürüyüş yollarının kenarına çınar, ıhlamur ve akçaağaç fidanı dikecektir. Fidan sayıları tabloda verilmiştir. Her sırada yalnızca tek tür fidan bulunacak, bütün sıralarda eşit sayıda fidan olacak ve hiçbir fidan artmayacaktır. Belediye, sıra sayısını olabildiğince az tutmak istemektedir.\n**Buna göre bu fidanlar toplam kaç sıraya dikilir?**",
  gorsel: "<table class=\"tablo\"><tr><th>Fidan türü</th><th>Fidan sayısı</th></tr><tr><td>Çınar</td><td>48</td></tr><tr><td>Ihlamur</td><td>72</td></tr><tr><td>Akçaağaç</td><td>120</td></tr></table>",
  secenekler: ["24","10","8","5"],
  dogru: 1,
  hatalar: ["EBOB'u, yani bir sıradaki fidan sayısını cevap sanma.",null,"Çınar sırasını (2) eklemeyi unutma: 3 + 5 = 8.","Yalnızca akçaağaçların sıra sayısını bulma."],
  aciklama: "Sıra sayısı en az olacağına göre bir sıradaki fidan sayısı en büyük olmalıdır; bu sayı üç sayıyı da kalansız bölmelidir. Yani EBOB aranır.\nAdım 1: 48 = 2^{4} · 3, 72 = 2^{3} · 3^{2}, 120 = 2^{3} · 3 · 5. Ortak asallar 2 ve 3; küçük üsler: EBOB = 2^{3} · 3 = 24.\nAdım 2: Sıra sayıları: 48 : 24 = 2, 72 : 24 = 3, 120 : 24 = 5.\nAdım 3: Toplam 2 + 3 + 5 = 10 sıra.\nSağlama: 10 sıra · 24 fidan = 240 = 48 + 72 + 120.\nSık yapılan hata: EBOB'da durmak. 24 bir sıradaki fidan sayısıdır, sıra sayısı değil.\nCevap B."
},
{
  id: "mat-ck-257",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Ada, bir bilgi yarışması için sayı kartı hazırlamaktadır. Kartta sayının asal çarpanlarına ayrılmış biçimi 2^{a} · 3 olarak yazılmış ve bu sayının tam 12 pozitif tam sayı çarpanı olduğu belirtilmiştir. Yarışmacılar önce a'nın değerini bulacak, sonra kartın sayısını hesaplayacaktır.\n**Buna göre kartta yazılı sayı kaçtır?**",
  gorsel: null,
  secenekler: ["96","192","384","6144"],
  dogru: 0,
  hatalar: [null,"a'yı 6 alma: 2^{6} · 3 sayısının 14 çarpanı vardır.","a'yı 7 alma: 2^{7} · 3 sayısının 16 çarpanı vardır.","(a + 1) = 12 sanıp a = 11 alma; oysa çarpan sayısı (a + 1) · 2 olur, 2^{11} · 3'ün 24 çarpanı vardır."],
  aciklama: "Üsleri birer artırıp çarpmak çarpan sayısını verir. Burada çarpan sayısı (a + 1) · (1 + 1) olur.\nAdım 1: (a + 1) · 2 = 12 → a + 1 = 6 → a = 5.\nAdım 2: Sayı 2^{5} · 3 = 32 · 3 = 96.\nSağlama: 96'nın çarpanları 1, 2, 3, 4, 6, 8, 12, 16, 24, 32, 48, 96; tam 12 tane.\nSık yapılan hata: Çarpan sayısını 3'ün üssünü hesaba katmadan yazmak. Her asal çarpanın (üs + 1) kadar katkısı vardır.\nCevap A."
},
{
  id: "mat-ck-258",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Bir tiyatro oyununda iki ışık efekti vardır: A efekti 15 saniyede bir, B efekti 20 saniyede bir çalışır. Oyun başladığı anda ikisi birlikte çalışmıştır ve oyun tam 1 saat 30 dakika sürmüştür. İki efekt birlikte çalıştığında sahnede \"çift\" yazısı yanmaktadır. Oyunun başladığı an ve bittiği an da sayılacaktır (bitiş anında da iki efekt birlikte çalışmaktadır).\n**Buna göre oyun boyunca \"çift\" yazısı kaç kez yanmıştır?**",
  gorsel: null,
  secenekler: ["89","90","91","360"],
  dogru: 2,
  hatalar: ["Başlangıç ve bitiş anlarının ikisini de saymama.","Başlangıç anını saymama; 90 yalnızca başlangıçtan sonraki ortak anların sayısıdır.",null,"5400 : 15 işlemiyle yalnızca A efektinin çalışma sayısını bulma."],
  aciklama: "İki efektin birlikte çalıştığı anlar, 15 ile 20'nin ortak katı olan saniyelerdir.\nAdım 1: 15 = 3 · 5 ve 20 = 2^{2} · 5. EKOK = 2^{2} · 3 · 5 = 60 saniye. Efektler dakikada bir birlikte çalışır.\nAdım 2: Oyun 90 dakika, yani 5400 saniye sürmüştür. 5400 : 60 = 90 kez başlangıçtan sonra birlikte çalışmışlardır.\nAdım 3: Başlangıç anı da sayılacağı için 90 + 1 = 91.\nSağlama: Yazı 0., 1., 2., …, 90. dakikalarda yanar; bu 91 dakikadır.\nSık yapılan hata: Başlangıç anını unutmak (90). \"Başlangıç ve bitiş dahil\" ifadesi bölüme 1 ekletir.\nCevap C."
},
{
  id: "mat-ck-259",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 3,
  soru: "Matematik öğretmeni, aralarında asal sayılarla ilgili dört iddia yazmış ve bunlardan yalnızca birinin her durumda doğru olduğunu söylemiştir. Öğrenciler iddiaları doğrulamak ya da çürütmek için örnekler denemektedir.\n**Buna göre her durumda doğru olan iddia hangisidir?**",
  gorsel: null,
  secenekler: ["Aralarında asal olan iki sayıdan en az biri asaldır.","Biri asal olan iki sayı daima aralarında asaldır.","Ardışık iki tek sayı daima aralarında asaldır.","İki çift sayı bazen aralarında asal olur."],
  dogru: 2,
  hatalar: ["8 ve 9 aralarında asaldır; ikisi de asal değildir.","5 ve 10: biri asaldır ama ortak bölenleri 1 ve 5'tir.",null,"Çift sayıların ikisi de 2'ye bölünür; ortak bölenleri en az 2 olduğundan aralarında asal olamazlar."],
  aciklama: "İki sayının ortak böleni, farklarını da böler. Ardışık iki tek sayının farkı 2'dir; ortak bölen ancak 1 ya da 2 olabilir. Sayılar tek olduğu için 2 ortak bölen olamaz, geriye 1 kalır.\nAdım 1: \"Biri asal\" iddiası 5 ve 10 ile çürür.\nAdım 2: \"En az biri asal\" iddiası 8 ve 9 ile çürür.\nAdım 3: İki çift sayının ortak böleni en az 2'dir; \"bazen aralarında asal\" iddiası da yanlıştır.\nAdım 4: Ardışık tek sayılar için 9 ile 11, 15 ile 17, 25 ile 27 gibi örneklerde EBOB hep 1'dir ve yukarıdaki gerekçe bunun daima doğru olduğunu gösterir.\nSık yapılan hata: Bir iki örnekle denemeyle yetinmek. \"Daima\" diyen iddiayı bir karşı örnek çürütür; doğru olanı gerekçeyle anlarsın.\nCevap C."
},
{
  id: "mat-ck-260",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Bir okulda 1'den 40'a kadar numaralanmış 40 dolap vardır ve hepsi kapalıdır. Öğrenci kulübü, numarasının pozitif tam sayı çarpanlarının sayısı tek olan dolapları mavi renge boyayacaktır. Kulüp başkanı, 6 numaralı dolabın çarpanlarının 1, 2, 3 ve 6 olmak üzere 4 tane olduğunu, bu yüzden 6 numaralı dolabın boyanmayacağını söylemiştir.\n**Buna göre kaç dolap mavi renge boyanır?**",
  gorsel: null,
  secenekler: ["5","6","12","20"],
  dogru: 1,
  hatalar: ["1 numaralı dolabı saymama; 1'in tek bir çarpanı vardır.",null,"Asal numaralı dolapları sayma; 40'a kadar 12 asal sayı vardır ama asalların 2 çarpanı vardır.","Tek numaralı dolapları sayma; çarpan sayısı tek olmak ile numaranın tek olması farklı şeylerdir."],
  aciklama: "Çarpanlar çiftler hâlinde bulunur: a · b = sayı. Çarpan sayısının tek olması için bir çiftin iki elemanı eşit olmalıdır, yani sayı bir sayının kendisiyle çarpımı (a · a) olmalıdır.\nAdım 1: 40'a kadar böyle sayılar: 1 = 1 · 1, 4 = 2 · 2, 9 = 3 · 3, 16 = 4 · 4, 25 = 5 · 5, 36 = 6 · 6. 7 · 7 = 49 sınırı aşar.\nAdım 2: Altı dolap boyanır.\nSağlama: 36'nın çarpanları 1, 2, 3, 4, 6, 9, 12, 18, 36'dır: 9 tane, tek. 12'nin çarpanları 6 tanedir: çift.\nSık yapılan hata: 1'i unutmak ya da tek sayıları saymak.\nCevap B."
},
{
  id: "mat-ck-261",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Bir manav, sepetindeki cevizleri 6'şar 6'şar saydığında 2 ceviz, 8'er 8'er saydığında yine 2 ceviz artırmaktadır. Sepette 50'den az ceviz bulunmaktadır ve manav ceviz sayısının bu koşullara uyan en büyük değer olduğunu söylemektedir.\n**Buna göre sepette kaç ceviz vardır?**",
  gorsel: null,
  secenekler: ["2","24","26","50"],
  dogru: 2,
  hatalar: ["En küçük değeri bulma; soru en büyük değeri istiyor.","EKOK'u cevap sanıp artan 2 cevizi eklemeyi unutma.",null,"50'den az koşulunu '50 dahil' diye okuma; 50 verilen sınıra dahil değildir."],
  aciklama: "Ceviz sayısından 2 çıkarılırsa sayı hem 6'ya hem 8'e tam bölünür; yani 2 çıkarılmış sayı EKOK'un katıdır.\nAdım 1: EKOK(6, 8) = 24. Ceviz sayısı \"24'ün bir katı + 2\" biçimindedir: 2, 26, 50, 74…\nAdım 2: 50'den az olanlar 2 ve 26'dır; en büyüğü 26'dır.\nSağlama: 26 = 6 · 4 + 2 ve 26 = 8 · 3 + 2. İki sayımda da 2 ceviz artar.\nSık yapılan hata: Sınır değerini (50) almak. \"50'den az\" ifadesi 50'yi kapsamaz.\nCevap C."
},
{
  id: "mat-ck-262",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Bir sinema salonunda toplam 156 koltuk, dikdörtgensel biçimde sıralar hâlinde yerleştirilmiştir: her sırada eşit sayıda koltuk vardır ve sıra sayısı ile bir sıradaki koltuk sayısı ardışık iki doğal sayıdır. Salon müdürü, sıra sayısını ve bir sıradaki koltuk sayısını bulup toplamlarını kayda geçirecektir.\n**Buna göre sıra sayısı ile bir sıradaki koltuk sayısının toplamı kaçtır?**",
  gorsel: null,
  secenekler: ["25","32","43","80"],
  dogru: 0,
  hatalar: [null,"6 · 26 çiftini alma; çarpım 156 eder ama sayılar ardışık değildir.","4 · 39 çiftini alma; çarpım 156 eder ama sayılar ardışık değildir.","2 · 78 çiftini alma; çarpım 156 eder ama sayılar ardışık değildir."],
  aciklama: "Sıra sayısı ile sıradaki koltuk sayısının çarpımı 156'dır. Bu iki sayı, 156'nın çarpan çiftlerinden biridir ve ardışık olmalıdır.\nAdım 1: 156'nın çarpan çiftlerini yaz: 1 · 156, 2 · 78, 3 · 52, 4 · 39, 6 · 26, 12 · 13.\nAdım 2: Yalnızca 12 ile 13 ardışıktır.\nAdım 3: Toplam 12 + 13 = 25.\nSağlama: 12 · 13 = 156.\nSık yapılan hata: Çarpan çiftini seçip ardışık olma koşulunu denetlememek.\nCevap A."
},
{
  id: "mat-ck-263",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 3,
  soru: "Bir koleksiyoncu, 360 pulu bir albüme, her sayfada eşit sayıda pul olacak biçimde yerleştirecektir. Sayfa sayısı ile bir sayfadaki pul sayısı 1'den büyük ve aralarında asal olacaktır. Ayrıca sayfa sayısı, bir sayfadaki pul sayısından küçük olacaktır.\n**Buna göre bu albüm kaç farklı biçimde düzenlenebilir?**",
  gorsel: null,
  secenekler: ["6","4","3","2"],
  dogru: 2,
  hatalar: ["Sayfa sayısı pul sayısından küçük koşulunu uygulamayıp iki yönü de sayma (3 · 2).","1 sayfa, sayfada 360 pul biçimini de sayma; sayfa sayısı 1'den büyük olmalı.",null,"Uygun biçimlerden birini (örneğin 9 sayfa, sayfada 40 pul) atlama."],
  aciklama: "360 = 2^{3} · 3^{2} · 5. Çarpımı 360 olan ve aralarında asal olan iki sayı elde etmek için her asal çarpanın bütün kuvveti aynı sayıya gitmelidir.\nAdım 1: Asal kuvvetler: 8, 9 ve 5. Bunları iki gruba ayır: (8, 9) ve (5) → 72 ve 5; (8, 5) ve (9) → 40 ve 9; (9, 5) ve (8) → 45 ve 8; (8, 9, 5) ve (hiçbiri) → 360 ve 1.\nAdım 2: 360 ve 1 çifti elenir (1'den büyük olmalı). Kalanlar: (5, 72), (8, 45), (9, 40).\nAdım 3: Her çiftte küçük olan sayfa sayısıdır; 3 biçim vardır.\nSağlama: 5 · 72 = 8 · 45 = 9 · 40 = 360 ve her çiftte EBOB 1'dir.\nSık yapılan hata: (6, 60) ya da (10, 36) gibi aralarında asal olmayan çarpan çiftlerini saymak.\nCevap C."
},
{
  id: "mat-ck-264",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Bir terzi, uzunlukları 60 cm, 84 cm ve 108 cm olan üç kumaş şeridi, hiç artmayacak biçimde, eşit uzunlukta ve olabildiğince uzun parçalara kesecektir. Her parçanın uzunluğu santimetre cinsinden bir tam sayıdır.\n**Buna göre terzi toplam kaç parça elde eder?**",
  gorsel: null,
  secenekler: ["12","18","21","252"],
  dogru: 2,
  hatalar: ["EBOB'u, yani bir parçanın uzunluğunu cevap sanma.","Parça sayısı yerine kesim sayısını bulma: 4 + 6 + 8 = 18.",null,"Şeritlerin uzunluklarını toplama (60 + 84 + 108 = 252)."],
  aciklama: "Parçalar eşit, artmayan ve en uzun olacağı için parça uzunluğu üç sayının EBOB'udur.\nAdım 1: 60 = 2^{2} · 3 · 5, 84 = 2^{2} · 3 · 7, 108 = 2^{2} · 3^{3}. Ortak asallar 2 ve 3; küçük üsler: EBOB = 2^{2} · 3 = 12 cm.\nAdım 2: Parça sayıları: 60 : 12 = 5, 84 : 12 = 7, 108 : 12 = 9.\nAdım 3: Toplam 5 + 7 + 9 = 21 parça.\nSağlama: 21 · 12 = 252 = 60 + 84 + 108.\nSık yapılan hata: EBOB'da durmak (12) ya da kesim sayısını (18) parça sayısı sanmak.\nCevap C."
},
{
  id: "mat-ck-265",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Deniz, bir sayı oyunu için tam üç farklı asal çarpanı bulunan ve bu asal çarpanların toplamı 10 olan iki basamaklı sayıları listeleyecektir. Örneğin asal çarpanları 2, 3 ve 7 olan 42, asal çarpanlarının toplamı 12 olduğu için listeye girmez.\n**Buna göre Deniz'in listesinde kaç sayı olur?**",
  gorsel: null,
  secenekler: ["3","4","5","6"],
  dogru: 0,
  hatalar: [null,"120'yi de sayma; 120 üç basamaklıdır.","120 ve 150'yi de sayma; ikisi de üç basamaklıdır.","30'un katı olan 120, 150 ve 180'i de sayma; bu sayılar üç basamaklıdır."],
  aciklama: "Üç farklı asal sayının toplamı 10 ise bu asallar 2, 3 ve 5'tir (en küçük üç asalın toplamı zaten 10'dur; başka seçenek yoktur).\nAdım 1: Sayı 2, 3 ve 5 çarpanlarının üçünü de içerir; yani 30'un katıdır ve başka asal çarpanı olamaz.\nAdım 2: 30'un iki basamaklı katları: 30, 60, 90.\nAdım 3: Üçünü de denetle: 30 = 2 · 3 · 5, 60 = 2^{2} · 3 · 5, 90 = 2 · 3^{2} · 5. Hepsinde yalnızca 2, 3 ve 5 var.\nSağlama: Sıradaki katlar 120, 150, 180 üç basamaklıdır.\nSık yapılan hata: Basamak koşulunu denetlemeden 30'un bütün katlarını saymak.\nCevap A."
},
{
  id: "mat-ck-266",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Üç arkadaş Mart ayının 1'inde kütüphanede buluşmuştur. Ada 6 günde bir, Berk 8 günde bir, Can 12 günde bir kütüphaneye gitmektedir ve düzenlerini değiştirmemişlerdir. Mart ayı 31 gündür.\n**Buna göre üçü, 1 Mart'tan sonra ilk kez hangi tarihte kütüphanede yeniden birlikte olur?**",
  gorsel: null,
  secenekler: ["13 Mart","26 Mart","18 Nisan","25 Mart"],
  dogru: 3,
  hatalar: ["12 gün sonrası Ada ve Can için doğrudur ama Berk için değil; 12, 8'in katı değildir.","24 gün sonrası yerine 25 gün sonrasını alma; saymaya 1 Mart'ı 1. gün olarak başlama.","48 gün sonrasını alma; bu, ikinci ortak gündür, ilk ortak gün değil.",null],
  aciklama: "Üçünün yeniden birlikte olduğu gün, 1 Mart'tan sonra hem 6'nın, hem 8'in, hem 12'nin katı kadar gün geçen gündür. İlk buluşma için EKOK aranır.\nAdım 1: 6 = 2 · 3, 8 = 2^{3}, 12 = 2^{2} · 3. EKOK = 2^{3} · 3 = 24 gün.\nAdım 2: 1 Mart + 24 gün = 25 Mart.\nSağlama: Ada 7, 13, 19, 25 Mart'ta; Berk 9, 17, 25 Mart'ta; Can 13, 25 Mart'ta gider. İlk ortak gün 25 Mart'tır.\nSık yapılan hata: Tarihe gün eklerken saymaya başlangıç gününden başlamak. \"24 gün sonra\" derken 1 Mart 0. gündür.\nCevap D."
},
{
  id: "mat-ck-267",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Bir otoparkta park yerlerinin numaraları 10'dan 99'a kadar iki basamaklı sayılardır. Bir sayının en küçük asal çarpanına o sayının \"kodu\" denir. Örneğin 35 = 5 · 7 sayısının kodu 5, 49 = 7 · 7 sayısının kodu 7'dir. Otopark yönetimi, numarasının kodu 5 olan park yerlerini ziyaretçilere ayıracaktır.\n**Buna göre kaç park yeri ziyaretçilere ayrılır?**",
  gorsel: null,
  secenekler: ["3","5","6","9"],
  dogru: 2,
  hatalar: ["3'e bölünen 15, 45 ve 75'i sayıp cevap sanma; asıl istenen, 5'in tek katları arasından bunların dışında kalanlardır.","Uygun bir numarayı atlama (örneğin 95 = 5 · 19); 5'in katı olup 2 ya da 3'e bölünmeyen 6 sayı vardır.",null,"3'e bölünen 15, 45 ve 75'i de listede tutma; bu sayıların en küçük asal çarpanı 3'tür, 5 değil."],
  aciklama: "Bir sayının kodu 5 ise sayı 5'e bölünür ama 5'ten küçük asal sayılara, yani 2'ye ve 3'e bölünmez. Aksi hâlde en küçük asal çarpan 5 olamazdı.\nAdım 1: 5'in iki basamaklı katları: 10, 15, 20, …, 95. Çift olanlar 2'ye bölündüğü için elenir; kalanlar 15, 25, 35, 45, 55, 65, 75, 85, 95 olur.\nAdım 2: Bunlardan 3'e bölünenleri çıkar: 15 (1 + 5 = 6), 45 (4 + 5 = 9) ve 75 (7 + 5 = 12). Kalanlar 25, 35, 55, 65, 85, 95.\nAdım 3: Say: 6 park yeri.\nSağlama: 25 = 5 · 5, 35 = 5 · 7, 55 = 5 · 11, 65 = 5 · 13, 85 = 5 · 17, 95 = 5 · 19; hepsinde en küçük asal çarpan 5'tir.\nSık yapılan hata: 3'e bölünme denetimini unutup 5'in bütün tek katlarını saymak (9).\nCevap C."
},
{
  id: "mat-ck-268",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 3,
  soru: "Matematik kulübünde Kaan ile Mina'nın kartlarında birbirinden farklı iki doğal sayı yazmaktadır. İki sayının toplamı 90, EBOB'ları 6'dır. Kulüp başkanı, kartlardaki sayı çiftinin kaç farklı biçimde olabileceğini merak etmektedir. Aynı iki sayı yer değiştirirse çift aynı kabul edilmektedir.\n**Buna göre bu özelliklere uyan kaç farklı sayı çifti vardır?**",
  gorsel: null,
  secenekler: ["3","4","7","8"],
  dogru: 1,
  hatalar: ["Bölüm çiftlerinden (1, 14) olanı, 1 içerdiği için aralarında asal saymama; (6, 84) çiftini unutma.",null,"Aralarında asal olma koşulunu uygulamadan bütün bölüm çiftlerini (a + b = 15) sayma.","Sayı çiftlerinin yerini değiştirip iki kez sayma (4 · 2)."],
  aciklama: "İki sayının EBOB'u 6 ise sayılar 6a ve 6b biçimindedir ve a ile b aralarında asaldır (EBOB'a bölünen sayılar aralarında asal olur).\nAdım 1: 6a + 6b = 90 → a + b = 15.\nAdım 2: a < b olacak biçimde çiftler: (1, 14), (2, 13), (3, 12), (4, 11), (5, 10), (6, 9), (7, 8).\nAdım 3: Aralarında asal olanlar: (1, 14), (2, 13), (4, 11), (7, 8). (3, 12), (5, 10), (6, 9) ortak bölen taşır.\nAdım 4: Sayı çiftleri: (6, 84), (12, 78), (24, 66), (42, 48). Toplam 4 çift.\nSağlama: EBOB(42, 48) = 6 ve 42 + 48 = 90.\nSık yapılan hata: Bölümlerin aralarında asal olması koşulunu denetlememek (7).\nCevap B."
},
{
  id: "mat-ck-269",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Ela ile Barış, birbirinden farklı birer doğal sayı seçmiştir. Seçilen iki sayının EBOB'u 9, EKOK'u 108'dir. Yarışma sunucusu, iki sayının toplamının alabileceği en küçük değeri sormaktadır.\n**Buna göre bu iki sayının toplamı en az kaçtır?**",
  gorsel: null,
  secenekler: ["63","108","117","972"],
  dogru: 0,
  hatalar: [null,"EKOK'un kendisini toplam sanma.","9 ile 108 çiftini alma; bu çift de koşulları sağlar ama toplamı en az olan çift değildir.","9 · 108 çarpımını toplam sanma."],
  aciklama: "İki sayının çarpımı EBOB · EKOK'a eşittir: 9 · 108 = 972. Sayılar 9a ve 9b biçimindedir ve a ile b aralarında asaldır.\nAdım 1: 9a · 9b = 972 → a · b = 12.\nAdım 2: Aralarında asal çarpan çiftleri: (1, 12) ve (3, 4). (2, 6) ortak bölen taşır, uygun değildir.\nAdım 3: (1, 12) → 9 ve 108, toplam 117. (3, 4) → 27 ve 36, toplam 63.\nAdım 4: En küçük toplam 63.\nSağlama: EBOB(27, 36) = 9, EKOK(27, 36) = 108.\nSık yapılan hata: Akla ilk gelen çifti (9 ve 108) alıp diğer çifti denemeden bırakmak.\nCevap A."
},
{
  id: "mat-ck-270",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Aşağıdaki tabloda bir A sayısının çarpan ağacındaki ayrışmalar verilmiştir. Her satırda soldaki sayı, sağdaki iki çarpanın çarpımına eşittir. 7 sayısı asaldır ve daha fazla ayrışmaz.\n**Buna göre A sayısının kaç pozitif tam sayı çarpanı vardır?**",
  gorsel: "<table class=\"tablo\"><tr><th>Sayı</th><th>Ayrışımı</th></tr><tr><td>A</td><td>2 · B</td></tr><tr><td>B</td><td>3 · C</td></tr><tr><td>C</td><td>5 · D</td></tr><tr><td>D</td><td>7 · 7</td></tr></table>",
  secenekler: ["4","5","16","24"],
  dogru: 3,
  hatalar: ["Farklı asal çarpan sayısını (2, 3, 5, 7) çarpan sayısı sanma.","Asal çarpanların adedini (2, 3, 5, 7, 7) çarpan sayısı sanma.","7'nin iki kez geçtiğini unutma: 2 · 2 · 2 · 2 = 16.",null],
  aciklama: "Önce A'yı en alttan yukarı doğru kur, sonra çarpan sayısını üslerden bul.\nAdım 1: D = 7 · 7 = 7^{2}. C = 5 · D = 5 · 7^{2}. B = 3 · C = 3 · 5 · 7^{2}. A = 2 · B = 2 · 3 · 5 · 7^{2} = 1470.\nAdım 2: Üsler: 2, 3 ve 5'in üssü 1; 7'nin üssü 2.\nAdım 3: Çarpan sayısı = (1 + 1) · (1 + 1) · (1 + 1) · (2 + 1) = 2 · 2 · 2 · 3 = 24.\nSağlama: 1470 = 2 · 3 · 5 · 49 ve 2 · 3 · 5 = 30 üç asalın çarpımıdır; 30'un 8 çarpanı, 7'nin üssüyle 8 · 3 = 24.\nSık yapılan hata: 7'nin iki kez geçtiğini üs olarak yazmayı unutmak.\nCevap D."
},
{
  id: "mat-ck-271",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Bir bilgi yarışmasında gizli, iki basamaklı bir sayı aranmaktadır. Sayı 6'ya, 8'e ve 9'a bölündüğünde her seferinde 5 kalmaktadır. Bu özelliği taşıyan iki basamaklı yalnızca bir sayı vardır.\n**Buna göre gizli sayı kaçtır?**",
  gorsel: null,
  secenekler: ["5","53","72","77"],
  dogru: 3,
  hatalar: ["Tek basamaklı sayıyı alma; 5 de her bölmede 5 kalır ama sayı iki basamaklı olmalıdır.","6 ve 8 için 24'ün katını alıp 9'u denetlememe: 53 = 9 · 5 + 8, kalan 5 değildir.","EKOK'u cevap sanma ve artan 5'i eklememe.",null],
  aciklama: "Sayıdan 5 çıkarılırsa sayı 6'ya, 8'e ve 9'a tam bölünür; yani 5 çıkarılmış sayı bu üç sayının ortak katıdır.\nAdım 1: EKOK(6, 8, 9): 6 = 2 · 3, 8 = 2^{3}, 9 = 3^{2}. EKOK = 2^{3} · 3^{2} = 72.\nAdım 2: Sayı \"72'nin bir katı + 5\" biçimindedir: 5, 77, 149…\nAdım 3: İki basamaklı olan 77'dir.\nSağlama: 77 = 6 · 12 + 5, 77 = 8 · 9 + 5, 77 = 9 · 8 + 5.\nSık yapılan hata: Yalnızca iki sayının EKOK'unu (24) alıp üçüncüyü denetlememek.\nCevap D."
},
{
  id: "mat-ck-272",
  kazanim: "M.8.1.1.3",
  kademe: 2,
  zorluk: 3,
  soru: "Paydası 60 olan, payı 30'dan büyük ve 60'tan küçük doğal sayılardan oluşan [[31|60]], [[32|60]], …, [[59|60]] kesirleri bir tahtaya yazılmıştır. Öğretmen, bu kesirler arasından sadeleştirilemeyenlerin sayısını sormaktadır.\n**Buna göre tahtadaki sadeleştirilemeyen kesirlerin sayısı kaçtır?**",
  gorsel: null,
  secenekler: ["7","8","12","16"],
  dogru: 1,
  hatalar: ["49'u unutma; 49 = 7^{2} asal değildir ama 60 ile aralarında asaldır.",null,"3'ü denetlemeyip yalnızca 2 ve 5 ile eleme yapma.","Pay koşulunu uygulamadan paydası 60 olan bütün sadeleşmeyen kesirleri (pay 1'den 59'a) sayma."],
  aciklama: "Bir kesrin sadeleşmemesi için pay ile payda aralarında asal olmalıdır. 60 = 2^{2} · 3 · 5 olduğundan pay 2'ye, 3'e ve 5'e bölünmemelidir.\nAdım 1: 31 ile 59 arasındaki tek sayılar: 31, 33, 35, 37, 39, 41, 43, 45, 47, 49, 51, 53, 55, 57, 59.\nAdım 2: 3'ün katlarını ele: 33, 39, 45, 51, 57. Kalanlar: 31, 35, 37, 41, 43, 47, 49, 53, 55, 59.\nAdım 3: 5'in katlarını ele: 35, 55. Kalanlar: 31, 37, 41, 43, 47, 49, 53, 59.\nAdım 4: Say: 8 kesir.\nSağlama: 49 = 7 · 7 ve 60 ile ortak asal çarpanı yoktur; [[49|60]] sadeleşmez.\nSık yapılan hata: Yalnızca asal payları saymak (7) ya da 3'ü denetlemeyi unutmak (12).\nCevap B."
},
{
  id: "mat-ck-273",
  kazanim: "M.8.1.1.1",
  kademe: 2,
  zorluk: 3,
  soru: "Bir bilgi yarışmasının son sorusunda, tam 15 tane pozitif tam sayı çarpanı olan en küçük doğal sayı istenmektedir. Yarışmacılar, çarpan sayısını asal çarpanlara ayrılmış biçimdeki üslerden hesaplayarak çözüme ulaşmaya çalışmaktadır.\n**Buna göre aranan sayı kaçtır?**",
  gorsel: null,
  secenekler: ["90","144","324","16384"],
  dogru: 1,
  hatalar: ["90 = 2 · 3^{2} · 5 sayısının çarpan sayısı 2 · 3 · 2 = 12'dir, 15 değil.",null,"324 = 2^{2} · 3^{4} de 15 çarpanlıdır ama büyük üssü küçük asal olan 2'ye vermediğin için en küçük değildir.","15 = 14 + 1 diye tek asal çarpanlı 2^{14}'ü alma; bu sayı da 15 çarpanlıdır ama çok büyüktür."],
  aciklama: "Çarpan sayısı, üslerin birer fazlasının çarpımıdır. Çarpan sayısının 15 olması için 15'i çarpanlarına ayır: 15 = 15 · 1 = 5 · 3.\nAdım 1: Tek asal çarpan: üs 14 → 2^{14} = 16384.\nAdım 2: İki asal çarpan: (4 + 1) · (2 + 1) = 15 → üsler 4 ve 2. Küçük sayı için büyük üsü küçük asala ver: 2^{4} · 3^{2} = 16 · 9 = 144. (Tersi 2^{2} · 3^{4} = 324.)\nAdım 3: Başka asallar daha büyük sayılar verir. En küçük 144'tür.\nSağlama: 144'ün çarpan sayısı (4 + 1) · (2 + 1) = 15.\nSık yapılan hata: Üslerin sırasını düşünmeden 324'ü ya da tek asal çarpanlı sayıyı seçmek.\nCevap B."
},
{
  id: "mat-ck-274",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Bir yazılım dersinde A = 2^{4} · 3^{2} · 7 ve B = 2^{2} · 3^{3} · 5 · 7 sayıları asal çarpanlarına ayrılmış biçimleriyle verilmiştir. Öğrenciler, hem A'yı hem B'yi kalansız bölen bütün pozitif tam sayıları bulmaya çalışmaktadır.\n**Buna göre A ve B sayılarının kaç ortak pozitif böleni vardır?**",
  gorsel: null,
  secenekler: ["9","12","18","30"],
  dogru: 2,
  hatalar: ["Ortak asal çarpan 7'yi unutma: (2 + 1) · (2 + 1) = 9.","3'ün ortak üssünü 1 alma: (2 + 1) · (1 + 1) · (1 + 1) = 12.",null,"Yalnızca A'nın çarpan sayısını bulma: (4 + 1) · (2 + 1) · (1 + 1) = 30."],
  aciklama: "Ortak bölenler, EBOB'un bölenleridir. Önce EBOB'u bul, sonra çarpan sayısını hesapla.\nAdım 1: Ortak asallar 2, 3 ve 7'dir (5 yalnızca B'de). Küçük üsler: 2'de 2, 3'te 2, 7'de 1.\nAdım 2: EBOB = 2^{2} · 3^{2} · 7 = 252.\nAdım 3: Çarpan sayısı = (2 + 1) · (2 + 1) · (1 + 1) = 18.\nSağlama: 252 = 4 · 9 · 7 ve 252, A = 16 · 9 · 7 = 1008'i (1008 : 252 = 4) böler.\nSık yapılan hata: Ortak olmayan asalları (5) ya da ortak olan 7'yi hesaba katmamak.\nCevap C."
},
{
  id: "mat-ck-275",
  kazanim: "M.8.1.1.2",
  kademe: 2,
  zorluk: 3,
  soru: "Bir sayı, 4'e, 5'e ve 6'ya bölündüğünde her seferinde 3 kalıyor; 7'ye ise kalansız bölünüyor. Bu özelliklere uyan sayılar küçükten büyüğe sıralandığında en baştaki sayı Hazal'ın kartına yazılmıştır.\n**Buna göre Hazal'ın kartındaki sayı kaçtır?**",
  gorsel: null,
  secenekler: ["3","60","63","123"],
  dogru: 2,
  hatalar: ["7'ye bölünme koşulunu denetlemeden 60 · 0 + 3 değerini alma; 3, 7'ye bölünmez.","EKOK'u cevap sanma; kalan 3 eklenmemiş, 7'ye bölünme de denetlenmemiş.",null,"İkinci değeri alma; 123 = 7 · 17 + 4, 7'ye bölünmez."],
  aciklama: "Sayıdan 3 çıkarılırsa sayı 4'e, 5'e ve 6'ya tam bölünür; yani sayı \"EKOK'un bir katı + 3\" biçimindedir.\nAdım 1: EKOK(4, 5, 6): 4 = 2^{2}, 5, 6 = 2 · 3. EKOK = 2^{2} · 3 · 5 = 60.\nAdım 2: Sayı 60k + 3: 3, 63, 123, 183…\nAdım 3: 7'ye bölünen ilk değeri ara: 3 bölünmez, 63 = 7 · 9 bölünür.\nSağlama: 63 = 4 · 15 + 3 = 5 · 12 + 3 = 6 · 10 + 3 ve 63 = 7 · 9.\nSık yapılan hata: İlk değerde (3) durmak. Üç koşulu birden denetle.\nCevap C."
}
);
